contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);
        // initial balance before deposit
        uint beforeBal = c.balances(address(this));
        uint beforeEth = address(c).balance;
        // make the deposit
        c.Deposit{value: depositAmount}();
        // read after values
        uint afterBal = c.balances(address(this));
        uint afterEth = address(c).balance;
        // general rule: deposit increases sender's balance and c's Ether balance by the exact amount
        assert(afterBal == beforeBal + depositAmount && afterEth == beforeEth + depositAmount);
    }
    receive() external payable {}
}

